  ChevronRight,
  Command,
  Cpu,
  Layers,
  Maximize2,
  Minimize2,
  Network,
  Radio,
  Router,
  Search,
  Server,
  Shield,
  Sparkles,
  Terminal,
} from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { cn, type DeviceStatus, type TopologyDevice } from './topology-types.js';
import { useTopologyShell } from './topology-context.js';
import { TopologyControls } from './topology-controls.js';

export interface TopologyStageProps {
  /**
   * Optional custom URL if an embedded diagram is explicitly desired.
   * If omitted, renders the clean workspace stage without any diagram.
   */
  src?: string;
  /** Show the in-stage title & toolbar */
  showToolbar?: boolean;
  /** Show floating camera controls HUD (+ / - / fit / fullscreen) */
  showControls?: boolean;
  /** Custom overlay children or slot */
  children?: React.ReactNode;
  /** Optional custom CSS classes on the container */
  className?: string;
}

const STATUS_LED_COLOR: Record<DeviceStatus, string> = {
  up: '#10b981',
  degraded: '#f59e0b',
  down: '#f43f5e',
  planned: '#0ea5e9',
  unknown: '#71717a',
};

function getDeviceIcon(tier: string, role: string) {
  const r = role.toLowerCase();
  if (r.includes('firewall') || r.includes('security') || r.includes('dmz')) return Shield;
  if (r.includes('router') || tier === 'edge') return Router;
  if (r.includes('server') || r.includes('cluster') || r.includes('db') || tier === 'endpoint') return Server;
  return Network;
}

export function TopologyStage({
  src,
  showToolbar = true,
  showControls = true,
  children,
  className,
}: TopologyStageProps) {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const { data, selectedDevice, activeZoneId, viewSettings, setSearchOpen } = useTopologyShell();

  const activeZone = data.zones.find((z) => z.id === (activeZoneId || selectedDevice?.zone));
  const activeZoneLabel = activeZone?.label || 'All Zones';

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen?.().then(() => setIsFullscreen(true)).catch(() => {});
    } else {
      document.exitFullscreen?.().then(() => setIsFullscreen(false)).catch(() => {});
    }
  };

  useEffect(() => {
    const handleFsChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };
    document.addEventListener('fullscreenchange', handleFsChange);
    return () => document.removeEventListener('fullscreenchange', handleFsChange);
  }, []);

  const DeviceIcon = selectedDevice
    ? getDeviceIcon(selectedDevice.tier, selectedDevice.role)
    : Network;

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative flex flex-col flex-1 min-h-[460px] w-full h-full overflow-hidden rounded-xl border border-fd-border/60 bg-fd-card/40 text-fd-foreground shadow-inner select-none transition-all',
        isFullscreen ? 'fixed inset-0 z-50 rounded-none border-0' : '',
        className,
      )}
    >
      {/* ── Top Floating Stage Bar: Breadcrumb + Search Trigger ── */}
      {showToolbar && (
        <div className="absolute top-3 inset-x-3 z-20 flex flex-wrap items-center justify-between gap-2 pointer-events-none">
          {/* Left: Breadcrumbs */}
          <div className="pointer-events-auto flex items-center gap-2 px-3 py-1.5 rounded-xl border border-fd-border/70 bg-fd-background/90 backdrop-blur-md shadow-xs">
            <Layers className="size-3.5 text-fd-primary" />
            <span className="text-xs font-semibold text-fd-foreground tracking-tight">
              {data.title || 'Marrow Studio'}
            </span>
            <ChevronRight className="size-3 text-fd-muted-foreground/60" />
            <span className="text-[11px] font-mono text-fd-primary">
              {activeZoneLabel}
            </span>
          </div>

          {/* Right: Quick Search Button + Fullscreen */}
          <div className="pointer-events-auto flex items-center gap-1.5">
            <button
              type="button"
              onClick={() => setSearchOpen(true)}
              className="inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border border-fd-border/70 bg-fd-background/90 backdrop-blur-md text-xs font-medium text-fd-muted-foreground hover:text-fd-foreground hover:border-fd-primary/50 transition-all shadow-xs cursor-pointer"
            >
              <Search className="size-3.5 text-fd-muted-foreground" />
              <span className="hidden sm:inline">Search devices…</span>
              <kbd className="px-1.5 py-0.2 text-[10px] font-mono bg-fd-muted border border-fd-border rounded text-fd-muted-foreground">
                Ctrl K
              </kbd>
            </button>

            <button
              type="button"
              onClick={toggleFullscreen}
              title={isFullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
              className="p-1.5 rounded-xl border border-fd-border/70 bg-fd-background/90 backdrop-blur-md text-fd-muted-foreground hover:text-fd-foreground transition-all shadow-xs cursor-pointer"
            >
              {isFullscreen ? <Minimize2 className="size-3.5" /> : <Maximize2 className="size-3.5" />}
            </button>
          </div>
        </div>
      )}

      {/* ── Main Stage Area: Clean Workspace Viewport (No Topology Diagram) ── */}
      <div className="relative flex-1 flex flex-col items-center justify-center p-6 w-full h-full min-h-[400px] overflow-hidden bg-fd-background/60">
        {/* Subtle Engineering Dot Grid */}
        <div
          aria-hidden="true"
          className="absolute inset-0 pointer-events-none opacity-[0.25]"
          style={{
            backgroundImage:
              'radial-gradient(var(--color-fd-border, #3f3f46) 1.2px, transparent 1.2px)',
            backgroundSize: '20px 20px',
          }}
        />

        {src ? (
          <iframe
            src={src}
            title={data.title}
            className="relative z-10 w-full h-full border-0 block"
            allow="fullscreen"
          />
        ) : (
          /* Active Hardware Telemetry Stage Card */
          <div className="relative z-10 flex flex-col items-center gap-4 w-full max-w-lg">
            {selectedDevice ? (
              <div className="w-full rounded-2xl border border-fd-border/80 bg-fd-card/90 backdrop-blur-md p-5 shadow-xl transition-all">
                {/* Header Row */}
                <div className="flex items-center justify-between pb-3 border-b border-fd-border/50">
                  <div className="flex items-center gap-3">
                    <div className="flex items-center justify-center size-10 rounded-xl bg-fd-primary/10 border border-fd-primary/20 text-fd-primary shadow-xs">
                      <DeviceIcon className="size-5" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-sm text-fd-foreground">
                          {selectedDevice.label}
                        </span>
                        <span
                          className="size-2 rounded-full inline-block shadow-xs"
                          style={{
                            backgroundColor:
                              STATUS_LED_COLOR[selectedDevice.status] || '#10b981',
                          }}
                          title={`Status: ${selectedDevice.status.toUpperCase()}`}
                        />
                      </div>
                      <span className="text-xs text-fd-muted-foreground">
                        {selectedDevice.role}
                      </span>
                    </div>
                  </div>

                  <span className="text-[10px] font-mono px-2 py-0.5 rounded-full border border-fd-border bg-fd-muted/70 text-fd-muted-foreground uppercase tracking-wider">
                    Tier: {selectedDevice.tier}
                  </span>
                </div>

                {/* Hardware Telemetry Spec Grid */}
                <div className="grid grid-cols-2 gap-2.5 py-3.5 text-xs">
                  <div className="flex flex-col gap-0.5 p-2 rounded-xl bg-fd-background/50 border border-fd-border/40">
                    <span className="text-[10px] font-mono uppercase tracking-wider text-fd-muted-foreground">
                      Management IP
                    </span>
                    <span className="font-mono font-medium text-fd-foreground">
                      {selectedDevice.ip || 'DHCP Assigned'}
                    </span>
                  </div>

                  <div className="flex flex-col gap-0.5 p-2 rounded-xl bg-fd-background/50 border border-fd-border/40">
                    <span className="text-[10px] font-mono uppercase tracking-wider text-fd-muted-foreground">
                      Hardware Model
                    </span>
                    <span className="font-medium truncate text-fd-foreground" title={selectedDevice.model}>
                      {selectedDevice.model || 'Standard Chassis'}
                    </span>
                  </div>

                  <div className="flex flex-col gap-0.5 p-2 rounded-xl bg-fd-background/50 border border-fd-border/40">
                    <span className="text-[10px] font-mono uppercase tracking-wider text-fd-muted-foreground">
                      Network OS
                    </span>
                    <span className="font-medium truncate text-fd-foreground" title={selectedDevice.os}>
                      {selectedDevice.os || 'Enterprise OS'}
                    </span>
                  </div>

                  <div className="flex flex-col gap-0.5 p-2 rounded-xl bg-fd-background/50 border border-fd-border/40">
                    <span className="text-[10px] font-mono uppercase tracking-wider text-fd-muted-foreground">
                      Interfaces Configured
                    </span>
                    <span className="font-mono font-medium text-fd-primary">
                      {selectedDevice.interfaces.length} Connected Ports
                    </span>
                  </div>
                </div>

                {/* Interactive Guidance Footer */}
                <div className="pt-2.5 border-t border-fd-border/50 flex items-center justify-between text-[11px] text-fd-muted-foreground">
                  <span className="flex items-center gap-1.5">
                    <Activity className="size-3.5 text-fd-primary" />
                    <span>Telemetry synced with right Inspector drawer</span>
                  </span>
                  <span className="font-mono text-[10px] text-fd-muted-foreground/70">
                    Zone: {selectedDevice.zone.toUpperCase()}
                  </span>
                </div>
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center p-8 text-center rounded-2xl border border-dashed border-fd-border bg-fd-card/40">
                <Network className="size-8 text-fd-muted-foreground/50 mb-2" />
                <span className="text-sm font-semibold text-fd-foreground">No Hardware Selected</span>
                <span className="text-xs text-fd-muted-foreground mt-1 max-w-xs">
                  Click any device in the left sidebar or press Ctrl+K to inspect telemetry.
                </span>
              </div>
            )}

            {/* Stage Purpose Callout */}
            <div className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-fd-border/60 bg-fd-muted/40 text-[11px] text-fd-muted-foreground">
              <Sparkles className="size-3 text-fd-primary" />
              <span>Workspace Stage frames device selection, sidebar, and inspector controls</span>
            </div>
          </div>
        )}

        {/* Custom Overlay Children */}
        {children}

        {/* Floating Camera Controls HUD */}
        {showControls && <TopologyControls />}

        {/* Bottom Left Engineering Blueprint Watermark */}
        {viewSettings?.watermark !== 'off' && (
          <div
            aria-hidden="true"
            className="absolute left-3.5 bottom-3 z-10 pointer-events-none select-none flex items-baseline gap-2"
          >
            <span className="text-[10px] font-mono font-semibold uppercase tracking-widest text-fd-muted-foreground/60">
              fig. 01 — Marrow Workspace Studio
            </span>
            <span className="hidden sm:inline text-[9px] font-mono text-fd-muted-foreground/40">
              Zero-Diagram Shell Mode
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

/** Export aliases so existing imports work cleanly */
export const TopologyCanvas = TopologyStage;
export const TopologyViewport = TopologyStage;

'use client';

import {
  Activity,
  ArrowRight,
  Cable,
  Check,
  Copy,
  Cpu,
  FileCode2,
  Layers,
  Network,
  Server,
  X,
} from 'lucide-react';
import { useState } from 'react';
import { cn, type DeviceStatus } from './topology-types.js';
import { useTopologyShell, type InspectorTab } from './topology-context.js';

const STATUS_BADGE: Record<DeviceStatus, { label: string; className: string; dot: string }> = {
  up: {
    label: 'Operational',
    className: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20',
    dot: 'bg-emerald-500',
  },
  degraded: {
    label: 'Degraded',
    className: 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20',
    dot: 'bg-amber-500',
  },
  down: {
    label: 'Fault / Down',
    className: 'bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20',
    dot: 'bg-rose-500',
  },
  planned: {
    label: 'Planned Window',
    className: 'bg-sky-500/10 text-sky-600 dark:text-sky-400 border-sky-500/20',
    dot: 'bg-sky-500',
  },
  unknown: {
    label: 'Unknown',
    className: 'bg-zinc-500/10 text-zinc-500 border-zinc-500/20',
    dot: 'bg-zinc-400',
  },
};

const TABS: { id: InspectorTab; label: string }[] = [
  { id: 'overview', label: 'Overview' },
  { id: 'interfaces', label: 'Interfaces' },
  { id: 'neighbors', label: 'Neighbors' },
  { id: 'metadata', label: 'Fields' },
  { id: 'config', label: 'Config' },
];

export function TopologyInspector({ className }: { className?: string }) {
  const {
    data,
    selectedDevice,
    selectedLink,
    inspectorOpen,
    setInspectorOpen,
    inspectorTab,
    setInspectorTab,
    focusDevice,
    selectLink,
    neighborsByDevice,
    linksByDevice,
  } = useTopologyShell();

  const [copied, setCopied] = useState(false);

  if (!inspectorOpen) return null;

  const deviceById = new Map(data.devices.map((d) => [d.id, d]));
  const zoneById = new Map(data.zones.map((z) => [z.id, z]));

  const handleCopyConfig = (text: string) => {
    navigator.clipboard?.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };

  return (
    <aside
      aria-label="Topology Inspector"
      className={cn(
        '[grid-area:right] flex flex-col w-[360px] xl:w-[380px] my-2 me-2 rounded-2xl border bg-fd-background shadow-sm overflow-hidden shrink-0 max-lg:fixed max-lg:inset-y-2 max-lg:right-2 max-lg:z-40 max-lg:shadow-2xl',
        className,
      )}
    >
      {/* Inspector Header */}
      <div className="flex items-start justify-between gap-3 px-4 py-3.5 border-b bg-fd-card/40 shrink-0">
        {selectedDevice ? (
          <div className="flex items-start gap-2.5 min-w-0">
            <div className="mt-0.5 flex items-center justify-center size-8 rounded-xl border bg-fd-secondary/60 text-fd-primary shrink-0">
              <Cpu className="size-4" />
            </div>
            <div className="flex flex-col min-w-0">
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-semibold font-mono text-fd-foreground truncate">
                  {selectedDevice.label}
                </h3>
                <span
                  className={cn(
                    'inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-medium border',
                    STATUS_BADGE[selectedDevice.status].className,
                  )}
                >
                  <span className={cn('size-1.5 rounded-full', STATUS_BADGE[selectedDevice.status].dot)} />
                  {STATUS_BADGE[selectedDevice.status].label}
                </span>
              </div>
              <p className="text-xs text-fd-muted-foreground truncate mt-0.5">
                {selectedDevice.role} · {selectedDevice.model ?? selectedDevice.tier}
              </p>
            </div>
          </div>
        ) : selectedLink ? (
          <div className="flex items-start gap-2.5 min-w-0">
            <div className="mt-0.5 flex items-center justify-center size-8 rounded-xl border bg-fd-secondary/60 text-fd-primary shrink-0">
              <Cable className="size-4" />
            </div>
            <div className="flex flex-col min-w-0">
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-semibold font-mono text-fd-foreground truncate">
                  {selectedLink.from.device} ↔ {selectedLink.to.device}
                </h3>
              </div>
              <p className="text-xs text-fd-muted-foreground truncate mt-0.5">
                {selectedLink.speed} {selectedLink.mode.toUpperCase()} Link ·{' '}
                {selectedLink.protocol ?? selectedLink.vlan ?? 'L2/L3'}
              </p>
            </div>
          </div>
        ) : (
          <div className="flex items-center gap-2.5">
            <div className="flex items-center justify-center size-8 rounded-xl border bg-fd-secondary/60 text-fd-muted-foreground">
              <Network className="size-4" />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-fd-foreground">Fabric Inspector</h3>
              <p className="text-xs text-fd-muted-foreground">Select any node or link on the stage</p>
            </div>
          </div>
        )}

        <button
          type="button"
          onClick={() => setInspectorOpen(false)}
          title="Close inspector (Esc)"
          aria-label="Close inspector"
          className="inline-flex items-center justify-center size-7 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors shrink-0"
        >
          <X className="size-4" />
        </button>
      </div>

      {/* Segmented Tabs Bar (when a device is selected) */}
      {selectedDevice && (
        <div
          role="tablist"
          className="flex items-center gap-0.5 mx-3 mt-3 p-1 rounded-xl border bg-fd-secondary/50 overflow-x-auto shrink-0"
        >
          {TABS.map((tab) => {
            const active = inspectorTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                role="tab"
                aria-selected={active}
                onClick={() => setInspectorTab(tab.id)}
                className={cn(
                  'flex-1 px-2.5 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
                  active
                    ? 'bg-fd-background text-fd-foreground shadow-xs border border-fd-border/60'
                    : 'text-fd-muted-foreground hover:text-fd-foreground',
                )}
              >
                {tab.label}
              </button>
            );
          })}
        </div>
      )}

      {/* Inspector Body */}
      <div className="flex-1 min-h-0 overflow-y-auto p-4 text-xs">
        {selectedDevice ? (
          <>
            {inspectorTab === 'overview' && (
              <div className="flex flex-col gap-4">
                {/* Identity & Addressing Grid */}
                <div className="rounded-xl border bg-fd-card/40 divide-y divide-fd-border/60">
                  {(
                    [
                      ['Hostname', selectedDevice.label, true],
                      ['Management IP', selectedDevice.ip ?? 'Unassigned', true],
                      ['Zone', zoneById.get(selectedDevice.zone)?.label ?? selectedDevice.zone, false],
                      ['Hierarchy Tier', selectedDevice.tier.toUpperCase(), true],
                      ['Hardware Model', selectedDevice.model ?? 'Generic Node', false],
                      ['OS Image', selectedDevice.os ?? 'N/A', true],
                      ...(selectedDevice.asn ? [['BGP ASN', `AS ${selectedDevice.asn}`, true] as const] : []),
                      ...(selectedDevice.serial ? [['Serial Number', selectedDevice.serial, true] as const] : []),
                      ...(selectedDevice.haPairWith
                        ? [['HA Redundancy Peer', selectedDevice.haPairWith, true] as const]
                        : []),
                    ] as const
                  ).map(([label, val, isMono]) => (
                    <div key={label} className="flex items-center justify-between px-3 py-2 gap-2">
                      <span className="text-fd-muted-foreground">{label}</span>
                      <span
                        className={cn(
                          'font-medium text-fd-foreground text-end truncate',
                          isMono && 'font-mono text-[11.5px]',
                        )}
                      >
                        {val}
                      </span>
                    </div>
                  ))}
                </div>

                {/* Quick Link Telemetry Summary */}
                <div className="rounded-xl border bg-fd-card/40 p-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="font-medium text-fd-foreground flex items-center gap-1.5">
                      <Activity className="size-3.5 text-fd-primary" />
                      Connected Fabric Links
                    </span>
                    <span className="font-mono text-[11px] text-fd-muted-foreground">
                      {(linksByDevice.get(selectedDevice.id) ?? []).length} links
                    </span>
                  </div>
                  <div className="flex flex-col gap-1.5">
                    {(linksByDevice.get(selectedDevice.id) ?? []).map((lnk) => {
                      const peerId =
                        lnk.from.device === selectedDevice.id ? lnk.to.device : lnk.from.device;
                      const localPort =
                        lnk.from.device === selectedDevice.id ? lnk.from.port : lnk.to.port;
                      const peerPort =
                        lnk.from.device === selectedDevice.id ? lnk.to.port : lnk.from.port;
                      return (
                        <button
                          key={lnk.id}
                          type="button"
                          onClick={() => selectLink(lnk.id)}
                          className="flex items-center justify-between px-2.5 py-1.5 rounded-lg border bg-fd-background hover:bg-fd-accent transition-colors text-start"
                        >
                          <div className="flex items-center gap-2 min-w-0">
                            <span
                              className={cn(
                                'size-2 rounded-full shrink-0',
                                STATUS_BADGE[lnk.status].dot,
                              )}
                            />
                            <span className="font-mono font-medium text-fd-foreground truncate">
                              {localPort}
                            </span>
                            <ArrowRight className="size-3 text-fd-muted-foreground shrink-0" />
                            <span className="font-mono text-fd-muted-foreground truncate">
                              {peerId}:{peerPort}
                            </span>
                          </div>
                          <span className="px-1.5 py-0.5 rounded bg-fd-secondary font-mono text-[10px] text-fd-muted-foreground shrink-0">
                            {lnk.speed}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>
            )}

            {inspectorTab === 'interfaces' && (
              <div className="flex flex-col gap-2">
                {selectedDevice.interfaces.map((iface) => (
                  <div
                    key={iface.name}
                    className="rounded-xl border bg-fd-card/40 p-3 flex flex-col gap-1.5"
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span
                          className={cn(
                            'size-2 rounded-full',
                            STATUS_BADGE[iface.status].dot,
                          )}
                        />
                        <span className="font-mono font-semibold text-fd-foreground">
                          {iface.name}
                        </span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        {iface.mode && (
                          <span className="px-1.5 py-0.5 rounded border bg-fd-background font-mono uppercase text-[10px] text-fd-muted-foreground">
                            {iface.mode}
                          </span>
                        )}
                        {iface.speed && (
                          <span className="px-1.5 py-0.5 rounded bg-fd-primary/10 text-fd-primary font-mono text-[10px] font-semibold">
                            {iface.speed}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-2 pt-1 text-[11px] text-fd-muted-foreground">
                      <div>
                        <span className="opacity-70">Address / VLAN: </span>
                        <span className="font-mono text-fd-foreground">
                          {iface.ip ?? (iface.vlan ? `VLAN ${iface.vlan}` : 'L2 Switchport')}
                        </span>
                      </div>
                      {iface.peerDevice && (
                        <div className="text-end truncate">
                          <span className="opacity-70">Peer: </span>
                          <button
                            type="button"
                            onClick={() => {
                              if (deviceById.has(iface.peerDevice!)) {
                                focusDevice(iface.peerDevice!);
                              }
                            }}
                            className="font-mono text-fd-primary hover:underline"
                          >
                            {iface.peerDevice} ({iface.peerPort})
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {inspectorTab === 'neighbors' && (
              <div className="flex flex-col gap-2">
                {Array.from(neighborsByDevice.get(selectedDevice.id) ?? []).map((peerId) => {
                  const peer = deviceById.get(peerId);
                  if (!peer) return null;
                  return (
                    <button
                      key={peer.id}
                      type="button"
                      onClick={() => focusDevice(peer.id)}
                      className="flex items-center justify-between p-3 rounded-xl border bg-fd-card/40 hover:bg-fd-accent transition-colors text-start"
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <Server className="size-4 text-fd-primary shrink-0" />
                        <div className="flex flex-col min-w-0">
                          <span className="font-mono font-semibold text-fd-foreground truncate">
                            {peer.label}
                          </span>
                          <span className="text-[11px] text-fd-muted-foreground truncate">
                            {peer.role} · {peer.ip ?? peer.tier}
                          </span>
                        </div>
                      </div>
                      <span
                        className={cn(
                          'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-medium border shrink-0',
                          STATUS_BADGE[peer.status].className,
                        )}
                      >
                        <span className={cn('size-1.5 rounded-full', STATUS_BADGE[peer.status].dot)} />
                        {peer.status}
                      </span>
                    </button>
                  );
                })}
              </div>
            )}

            {inspectorTab === 'metadata' && (
              <div className="flex flex-col gap-2">
                {selectedDevice.customFields &&
                Object.keys(selectedDevice.customFields).length > 0 ? (
                  Object.entries(selectedDevice.customFields).map(([key, val]) => (
                    <div
                      key={key}
                      className="rounded-xl border bg-fd-card/40 p-3 flex flex-col gap-1"
                    >
                      <span className="text-[11px] font-medium text-fd-muted-foreground uppercase tracking-wider">
                        {key}
                      </span>
                      <span className="font-mono text-xs text-fd-foreground">{val}</span>
                    </div>
                  ))
                ) : (
                  <p className="text-fd-muted-foreground py-6 text-center">
                    No custom metadata fields declared for this node.
                  </p>
                )}
              </div>
            )}

            {inspectorTab === 'config' && (
              <div className="flex flex-col gap-2">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-medium text-fd-muted-foreground flex items-center gap-1.5">
                    <FileCode2 className="size-3.5" />
                    Device Configuration Stanza
                  </span>
                  <button
                    type="button"
                    onClick={() =>
                      handleCopyConfig(
                        selectedDevice.configSnippet ??
                          `# ${selectedDevice.label}\nhostname ${selectedDevice.label}`,
                      )
                    }
                    className="inline-flex items-center gap-1 px-2 py-1 rounded-lg border bg-fd-secondary/60 hover:bg-fd-accent text-[11px] font-medium text-fd-foreground transition-colors"
                  >
                    {copied ? (
                      <>
                        <Check className="size-3 text-emerald-500" />
                        <span>Copied</span>
                      </>
                    ) : (
                      <>
                        <Copy className="size-3" />
                        <span>Copy CLI</span>
                      </>
                    )}
                  </button>
                </div>
                <pre className="p-3 rounded-xl border bg-fd-card/80 font-mono text-[11px] leading-relaxed text-fd-foreground overflow-x-auto">
                  <code>
                    {selectedDevice.configSnippet ??
                      `hostname ${selectedDevice.label}\n!\ninterface Loopback0\n ip address ${selectedDevice.ip ?? '10.255.0.1/32'}`}
                  </code>
                </pre>
              </div>
            )}
          </>
        ) : selectedLink ? (
          <div className="flex flex-col gap-4">
            <div className="rounded-xl border bg-fd-card/40 divide-y divide-fd-border/60">
              {(
                [
                  ['Link ID', selectedLink.id, true],
                  ['Endpoint A', `${selectedLink.from.device} (${selectedLink.from.port})`, true],
                  ['Endpoint B', `${selectedLink.to.device} (${selectedLink.to.port})`, true],
                  ['Bandwidth Speed', selectedLink.speed, true],
                  ['Logical Mode', selectedLink.mode.toUpperCase(), true],
                  ['Encapsulation / Protocol', selectedLink.protocol ?? selectedLink.vlan ?? 'Native', true],
                  ['Operational State', STATUS_BADGE[selectedLink.status].label, false],
                ] as const
              ).map(([k, v, mono]) => (
                <div key={k} className="flex items-center justify-between px-3 py-2 gap-2">
                  <span className="text-fd-muted-foreground">{k}</span>
                  <span className={cn('font-medium text-fd-foreground', mono && 'font-mono')}>
                    {v}
                  </span>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => focusDevice(selectedLink.from.device)}
                className="p-2.5 rounded-xl border bg-fd-card/40 hover:bg-fd-accent text-start transition-colors"
              >
                <span className="text-[10px] text-fd-muted-foreground uppercase block">
                  Source Device
                </span>
                <span className="font-mono font-semibold text-fd-primary">
                  {selectedLink.from.device}
                </span>
              </button>
              <button
                type="button"
                onClick={() => focusDevice(selectedLink.to.device)}
                className="p-2.5 rounded-xl border bg-fd-card/40 hover:bg-fd-accent text-start transition-colors"
              >
                <span className="text-[10px] text-fd-muted-foreground uppercase block">
                  Target Device
                </span>
                <span className="font-mono font-semibold text-fd-primary">
                  {selectedLink.to.device}
                </span>
              </button>
            </div>
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            <p className="text-fd-muted-foreground leading-relaxed">
              Click any router, switch, firewall, or link on the topology canvas to inspect its
              interfaces, BGP peering state, optic levels, and CLI stanzas.
            </p>
            <div className="rounded-xl border bg-fd-card/40 p-3 flex flex-col gap-2">
              <span className="font-medium text-fd-foreground flex items-center gap-1.5">
                <Layers className="size-3.5 text-fd-primary" />
                Quick Select Device
              </span>
              <div className="flex flex-col gap-1">
                {data.devices.slice(0, 5).map((dev) => (
                  <button
                    key={dev.id}
                    type="button"
                    onClick={() => focusDevice(dev.id)}
                    className="flex items-center justify-between px-2.5 py-1.5 rounded-lg hover:bg-fd-accent text-start transition-colors"
                  >
                    <span className="font-mono font-medium text-fd-foreground">{dev.label}</span>
                    <span className="text-[11px] text-fd-muted-foreground">{dev.role}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Inspector Footer */}
      <div className="px-4 py-2.5 border-t bg-fd-card/30 flex items-center justify-between text-[11px] text-fd-muted-foreground shrink-0">
        <span>Marrow Inspector</span>
        <span className="font-mono">Press Esc to close</span>
      </div>
    </aside>
  );
}

'use client';

import { Command, Map as MapIcon, Maximize2, Minus, Minimize2, Plus } from 'lucide-react';
import { useState } from 'react';
import { cn, type DeviceStatus } from './topology-types.js';
import { useTopologyShell } from './topology-context.js';

const MINI_DOT_COLOR: Record<DeviceStatus, string> = {
  up: '#10b981',
  degraded: '#f59e0b',
  down: '#f43f5e',
  planned: '#0ea5e9',
  unknown: '#71717a',
};

export function TopologyMinimap({ className }: { className?: string }) {
  const { data, camera, setCamera, selectedDeviceId, viewSettings } = useTopologyShell();
  const [collapsed, setCollapsed] = useState(false);

  if (!viewSettings.minimap) return null;

  const totalWidth = data.width ?? 1200;
  const totalHeight = data.height ?? 800;
  const miniW = 168;
  const miniH = Math.round((totalHeight / totalWidth) * miniW);

  // Viewport indicator box inside minimap coordinates
  const viewW = Math.min(totalWidth, totalWidth / camera.k);
  const viewH = Math.min(totalHeight, totalHeight / camera.k);
  const viewX = Math.max(
    0,
    Math.min(totalWidth - viewW, (totalWidth - viewW) / 2 - camera.x / camera.k),
  );
  const viewY = Math.max(
    0,
    Math.min(totalHeight - viewH, (totalHeight - viewH) / 2 - camera.y / camera.k),
  );

  return (
    <div
      className={cn(
        'absolute bottom-3 right-14 z-20 rounded-xl border bg-fd-popover/90 backdrop-blur-md shadow-md transition-all',
        collapsed ? 'p-1' : 'p-1.5',
        className,
      )}
    >
      {collapsed ? (
        <button
          type="button"
          onClick={() => setCollapsed(false)}
          title="Expand minimap"
          aria-label="Expand minimap"
          className="flex items-center justify-center size-8 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors"
        >
          <MapIcon className="size-4" />
        </button>
      ) : (
        <div className="relative group">
          <button
            type="button"
            onClick={() => setCollapsed(true)}
            title="Collapse minimap"
            aria-label="Collapse minimap"
            className="absolute top-1 right-1 z-10 flex items-center justify-center size-5 rounded-md border bg-fd-background/90 text-fd-muted-foreground opacity-0 group-hover:opacity-100 hover:text-fd-foreground transition-opacity"
          >
            <Minimize2 className="size-3" />
          </button>
          <svg
            width={miniW}
            height={miniH}
            viewBox={`0 0 ${totalWidth} ${totalHeight}`}
            className="block rounded-lg bg-fd-card/60 cursor-crosshair"
            onClick={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const clickX = ((e.clientX - rect.left) / rect.width) * totalWidth;
              const clickY = ((e.clientY - rect.top) / rect.height) * totalHeight;
              setCamera((prev) => ({
                ...prev,
                x: (totalWidth / 2 - clickX) * prev.k,
                y: (totalHeight / 2 - clickY) * prev.k,
              }));
            }}
          >
            {data.zones.map((z) => (
              <rect
                key={z.id}
                x={z.x}
                y={z.y}
                width={z.width}
                height={z.height}
                rx={12}
                fill={z.accent ?? '#3b82f6'}
                fillOpacity={0.12}
                stroke={z.accent ?? '#3b82f6'}
                strokeOpacity={0.45}
                strokeWidth={4}
              />
            ))}
            {data.devices.map((d) => (
              <circle
                key={d.id}
                cx={d.x}
                cy={d.y}
                r={selectedDeviceId === d.id ? 18 : 12}
                fill={MINI_DOT_COLOR[d.status]}
                stroke={selectedDeviceId === d.id ? '#ffffff' : 'none'}
                strokeWidth={5}
              />
            ))}
            <rect
              x={viewX}
              y={viewY}
              width={viewW}
              height={viewH}
              rx={10}
              fill="var(--color-fd-primary, #3b82f6)"
              fillOpacity={0.12}
              stroke="var(--color-fd-primary, #3b82f6)"
              strokeWidth={6}
            />
          </svg>
        </div>
      )}
    </div>
  );
}

export function TopologyControls({ className }: { className?: string }) {
  const { zoomIn, zoomOut, fitView, setSearchOpen } = useTopologyShell();

  return (
    <div
      aria-label="Camera controls"
      className={cn(
        'absolute bottom-3 right-3 z-20 flex flex-col gap-0.5 p-1 rounded-xl border bg-fd-popover/90 backdrop-blur-md shadow-md',
        className,
      )}
    >
      <button
        type="button"
        onClick={zoomIn}
        title="Zoom in (+)"
        aria-label="Zoom in"
        className="flex items-center justify-center size-8 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors"
      >
        <Plus className="size-4" />
      </button>
      <button
        type="button"
        onClick={zoomOut}
        title="Zoom out (−)"
        aria-label="Zoom out"
        className="flex items-center justify-center size-8 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors"
      >
        <Minus className="size-4" />
      </button>
      <button
        type="button"
        onClick={fitView}
        title="Fit view (F)"
        aria-label="Fit view"
        className="flex items-center justify-center size-8 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors"
      >
        <Maximize2 className="size-3.5" />
      </button>
      <div className="my-0.5 h-px bg-fd-border" />
      <button
        type="button"
        onClick={() => setSearchOpen(true)}
        title="Command center (Ctrl+K)"
        aria-label="Open command center"
        className="flex items-center justify-center size-8 rounded-lg text-fd-muted-foreground hover:bg-fd-accent hover:text-fd-foreground transition-colors"
      >
        <Command className="size-3.5" />
      </button>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef, useMemo } from "react";
import { cn } from "./topology-types.js";
import { useTopologyShell } from "./topology-context.js";

export interface TopologySearchProps {
  className?: string;
}

export function TopologySearch({ className }: TopologySearchProps) {
  const {
    data,
    searchOpen,
    setSearchOpen,
    focusDevice,
    selectLink,
    setActiveZoneId,
    fitView,
    viewSettings,
    updateViewSetting,
  } = useTopologyShell();

  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (searchOpen) {
      setQuery("");
      setSelectedIndex(0);
      requestAnimationFrame(() => {
        inputRef.current?.focus();
      });
    }
  }, [searchOpen]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();

    const matchedDevices = data.devices.filter(
      (d) =>
        !q ||
        d.label.toLowerCase().includes(q) ||
        d.id.toLowerCase().includes(q) ||
        d.ip?.toLowerCase().includes(q) ||
        d.role.toLowerCase().includes(q) ||
        d.zone.toLowerCase().includes(q) ||
        d.model?.toLowerCase().includes(q),
    );

    const matchedLinks = data.links.filter(
      (l) =>
        !q ||
        l.id.toLowerCase().includes(q) ||
        l.from.device.toLowerCase().includes(q) ||
        l.to.device.toLowerCase().includes(q) ||
        l.protocol?.toLowerCase().includes(q) ||
        l.speed.toLowerCase().includes(q),
    );

    const matchedZones = data.zones.filter(
      (z) =>
        !q ||
        z.label.toLowerCase().includes(q) ||
        z.id.toLowerCase().includes(q) ||
        z.subtitle?.toLowerCase().includes(q),
    );

    const items: Array<{
      id: string;
      category: "Device" | "Link" | "Zone" | "Command";
      title: string;
      subtitle: string;
      badge?: string;
      color?: string;
      onSelect: () => void;
    }> = [];

    for (const dev of matchedDevices.slice(0, 6)) {
      const zone = data.zones.find((z) => z.id === dev.zone);
      items.push({
        id: `dev:${dev.id}`,
        category: "Device",
        title: dev.label,
        subtitle: `${dev.ip ?? dev.id} · ${zone?.label ?? dev.zone}`,
        badge: dev.role,
        color: zone?.accent,
        onSelect: () => {
          focusDevice(dev.id);
          setSearchOpen(false);
        },
      });
    }

    for (const zone of matchedZones.slice(0, 4)) {
      items.push({
        id: `zone:${zone.id}`,
        category: "Zone",
        title: `Filter Zone: ${zone.label}`,
        subtitle: zone.subtitle ?? zone.id,
        badge: "Zone",
        color: zone.accent,
        onSelect: () => {
          setActiveZoneId(zone.id);
          setSearchOpen(false);
        },
      });
    }

    for (const link of matchedLinks.slice(0, 4)) {
      items.push({
        id: `link:${link.id}`,
        category: "Link",
        title: `${link.from.device} ↔ ${link.to.device}`,
        subtitle: `${link.from.port} → ${link.to.port}`,
        badge: `${link.speed} ${link.mode}`,
        onSelect: () => {
          selectLink(link.id);
          setSearchOpen(false);
        },
      });
    }

    const commands = [
      {
        id: "cmd:fit",
        title: "Fit Topology to Screen",
        subtitle: "Recenter camera and reset zoom to 100%",
        badge: "F",
        onSelect: () => {
          fitView();
          setSearchOpen(false);
        },
      },
      {
        id: "cmd:all-zones",
        title: "Show All Security Zones",
        subtitle: "Clear active security zone filter",
        badge: "All",
        onSelect: () => {
          setActiveZoneId(null);
          setSearchOpen(false);
        },
      },
      {
        id: "cmd:flow",
        title: "Toggle Animated Traffic Flow",
        subtitle: "Pause or resume packet flow animations on active links",
        badge: "Layer",
        onSelect: () => {
          updateViewSetting("motion", !viewSettings.motion);
          setSearchOpen(false);
        },
      },
    ].filter(
      (c) =>
        !q ||
        c.title.toLowerCase().includes(q) ||
        c.subtitle.toLowerCase().includes(q),
    );

    for (const cmd of commands) {
      items.push({
        ...cmd,
        category: "Command",
      });
    }

    return items;
  }, [
    data,
    query,
    focusDevice,
    selectLink,
    setActiveZoneId,
    fitView,
    viewSettings.motion,
    updateViewSetting,
    setSearchOpen,
  ]);

  useEffect(() => {
    setSelectedIndex(0);
  }, [query]);

  if (!searchOpen) return null;

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((prev) => (prev + 1) % Math.max(1, results.length));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex(
        (prev) => (prev - 1 + Math.max(1, results.length)) % Math.max(1, results.length),
      );
    } else if (e.key === "Enter" && results[selectedIndex]) {
      e.preventDefault();
      results[selectedIndex].onSelect();
    } else if (e.key === "Escape") {
      e.preventDefault();
      setSearchOpen(false);
    }
  };

  return (
    <div
      className={cn(
        "fixed inset-0 z-50 flex items-start justify-center bg-black/50 p-4 pt-[12vh] backdrop-blur-xs animate-in fade-in duration-150",
        className,
      )}
      onClick={() => setSearchOpen(false)}
      role="dialog"
      aria-modal="true"
      aria-label="Topology Command & Search"
    >
      <div
        className="w-full max-w-xl overflow-hidden rounded-2xl border border-fd-border bg-fd-popover text-fd-popover-foreground shadow-2xl"
        onClick={(e) => e.stopPropagation()}
        onKeyDown={handleKeyDown}
      >
        {/* Search Input Bar */}
        <div className="flex items-center gap-3 border-b border-fd-border px-4 py-3">
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className="size-4 shrink-0 text-fd-muted-foreground"
          >
            <circle cx="11" cy="11" r="8" />
            <path d="m21 21-4.3-4.3" />
          </svg>
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search devices, IPs, security zones, links, or commands..."
            className="w-full bg-transparent text-sm text-fd-foreground placeholder:text-fd-muted-foreground focus:outline-none"
          />
          <button
            type="button"
            onClick={() => setSearchOpen(false)}
            className="rounded-md border border-fd-border bg-fd-muted/50 px-1.5 py-0.5 font-mono text-[10px] text-fd-muted-foreground hover:text-fd-foreground"
          >
            ESC
          </button>
        </div>

        {/* Results List */}
        <div className="max-h-[360px] overflow-y-auto p-2">
          {results.length === 0 ? (
            <div className="py-10 text-center text-xs text-fd-muted-foreground">
              No matching devices, links, or commands for &ldquo;{query}&rdquo;.
            </div>
          ) : (
            <div className="space-y-1">
              {results.map((item, idx) => {
                const active = idx === selectedIndex;
                return (
                  <button
                    key={item.id}
                    type="button"
                    onMouseEnter={() => setSelectedIndex(idx)}
                    onClick={item.onSelect}
                    className={cn(
                      "flex w-full items-center justify-between gap-3 rounded-xl px-3 py-2 text-left transition-colors",
                      active
                        ? "bg-fd-accent text-fd-accent-foreground"
                        : "text-fd-foreground/85 hover:bg-fd-accent/50",
                    )}
                  >
                    <div className="flex min-w-0 items-center gap-2.5">
                      <span
                        className="size-2 shrink-0 rounded-full"
                        style={{
                          backgroundColor:
                            item.color ??
                            (item.category === "Command"
                              ? "#10b981"
                              : item.category === "Link"
                                ? "#6366f1"
                                : "#0ea5e9"),
                        }}
                      />
                      <div className="min-w-0">
                        <div className="truncate text-xs font-medium text-fd-foreground">
                          {item.title}
                        </div>
                        <div className="truncate font-mono text-[11px] text-fd-muted-foreground">
                          {item.subtitle}
                        </div>
                      </div>
                    </div>

                    <div className="flex shrink-0 items-center gap-1.5">
                      <span className="rounded-md border border-fd-border/70 bg-fd-background/70 px-1.5 py-0.5 font-mono text-[10px] uppercase text-fd-muted-foreground">
                        {item.badge ?? item.category}
                      </span>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Footer Hints */}
        <div className="flex items-center justify-between border-t border-fd-border bg-fd-muted/30 px-4 py-2 text-[11px] text-fd-muted-foreground">
          <div className="flex items-center gap-3">
            <span>
              <kbd className="rounded border border-fd-border bg-fd-background px-1 py-0.5 font-mono text-[10px]">
                ↑↓
              </kbd>{" "}
              Navigate
            </span>
            <span>
              <kbd className="rounded border border-fd-border bg-fd-background px-1 py-0.5 font-mono text-[10px]">
                ↵
              </kbd>{" "}
              Select
            </span>
          </div>
          <span className="font-mono text-[10px]">Marrow Command Center</span>
        </div>
      </div>
    </div>
  );
}
